function localKey(){return 'ly-editor-recovery-v1:'+accountUsername;}
function loadLocalDrafts(){try{const value=JSON.parse(localStorage.getItem(localKey())||'{}');localDrafts=value&&typeof value==='object'&&!Array.isArray(value)?value:{};}catch{localDrafts={};}}
