   if(draftContext===ctx){$('discard-editor-draft').hidden=false;if(!localDrafts[ctx.id]){dirty=false;autosaveStatus('已自动保存 · '+new Date(data.draft.updatedAt).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}));}else{dirty=true;autosaveStatus('有新的修改 · 即将保存');autosaveTimer=setTimeout(()=>autosaveDraft().catch(()=>{}),1200);}}
