function draftMetadata(d){return {content:d.content,topic:d.content.topic,id:d.id,sourceSlug:d.sourceSlug,sourceRevision:d.sourceRevision,revision:d.revision??d.baseRevision,title:d.content.title,kind:d.content.kind,date:d.content.date,updatedAt:d.updatedAt||d.changedAt,local:Boolean(d.changedAt)};}
