  $('reload-editor-draft').hidden=false;$('discard-editor-draft').hidden=false;schedulePreview(true);
  if(draft.sourceSlug&&(!source||source.trashedAt)){draftContext.conflict=true;autosaveStatus('原内容已删除或在回收站中 · 当前草稿可导出后新建',true);}
  else if(source&&source.revision!==draft.sourceRevision)autosaveStatus('原内容已在其他页面修改 · 当前编辑草稿已保留，发布前请核对',true);
