$('reload-editor-draft').addEventListener('click',async()=>{if(busy)return;if(draftContext&&confirm('重新载入服务器草稿会替换当前输入。需要时请先导出 Markdown。继续吗？')){if(autosavePending)try{await autosavePending;}catch{}await openEditorDraft(draftContext.id,{ignoreLocal:true});}});
