 $('save-post').textContent='保存草稿';$('publish-post').textContent=post.published?'更新发布':'发布';$('unpublish-post').hidden=!post.published||Boolean(post.trashedAt);$('visibility').textContent=post.trashedAt?'回收站':post.published?'已发布 · 修改先存草稿':'草稿';$('trash-notice').hidden=!post.trashedAt;
