function marked(tag,value,query,cls){const element=text(tag,'',cls);if(!searchCore||!query){element.textContent=value;return element;}for(const part of searchCore.highlightParts(value,query))element.append(part.match?text('mark',part.text):document.createTextNode(part.text));return element;}
