 const hits=searchCore?searchCore.searchContent(posts.map(record=>({record:organizedRecord(record)})),{q:search,kind,status:visibility,topic,order,organization:$('content-organization-filter').value}):posts.filter(p=>(!kind||(p.kind||'blog')===kind)&&p.title.toLowerCase().includes(search.toLowerCase())&&(visibility==='trash'?Boolean(p.trashedAt):!p.trashedAt&&(visibility==='draft'?!p.published:visibility==='published'?p.published:true))).map(p=>({id:p.slug}));
 $('list-count').textContent=(search?'匹配 ':'')+hits.length+' 条内容';$('post-list').replaceChildren();$('clear-content-search').hidden=!search;$('more-content').hidden=hits.length<=listLimit;
 for(const hit of hits.slice(0,listLimit)){const post=posts.find(p=>p.slug===hit.id),b=text('button','','post-row');b.type='button';b.dataset.slug=post.slug;b.setAttribute('aria-current',String(editing?.slug===post.slug));b.append(marked('strong',post.title,search),text('small',kindNames[post.kind||'blog']+' · '+(post.trashedAt?'回收站':post.published?'已发布':'草稿')+' · '+post.date));if(search){b.append(marked('span',hit.snippet||post.summary,search,'search-snippet'));b.append(text('small',(hit.matched||[]).map(name=>({title:'标题',summary:'摘要',body:'正文',topic:'分类',project:'项目资料',organization:'内容归属'}[name])).join(' / ')+'匹配','search-match-label'));}b.addEventListener('click',async()=>{if(canSwitch()){if(post.trashedAt)fill(post);else await openPost(post);focusSearchMatch(search);}});$('post-list').append(b);}
