 try{await autosaveDraft(true);const consumed=draftContext;post.editorDraft={id:consumed.id,revision:consumed.revision};const data=await request('/api/admin/posts',{method:original?'PUT':'POST',headers:original?{'If-Match':original.revision}:{},body:JSON.stringify(post)});delete localDrafts[consumed.id];writeLocalDrafts();try{sessionStorage.removeItem('ly-editor-current-v1');}catch{}editorDrafts=editorDrafts.filter(d=>d.id!==consumed.id);fill(data.post);await load();status(data.editorDraftRetained?'内容已保存；旧编辑草稿清理暂时未完成，可在草稿箱删除。':published?'已保存并发布，岛上现在可以看到。':'草稿已保存，只有你能看到。');}
