async function uploadImage(file){
 if(!file||busy||editing?.trashedAt)return;
 if(file.size>8*1024*1024){status('单张图片请控制在 8 MB 以内。',true);return;}
 const inferred=/\.(jpe?g)$/i.test(file.name)?'image/jpeg':/\.png$/i.test(file.name)?'image/png':/\.webp$/i.test(file.name)?'image/webp':'';const type=file.type||inferred;
 if(!['image/jpeg','image/png','image/webp'].includes(type)){status('请上传 JPG、PNG 或 WebP 图片。',true);return;}
 setBusy(true);status('正在上传并处理图片…');
 try{await sessionReady;const response=await fetch('/api/admin/media',{method:'POST',headers:{'Content-Type':type,'X-Requested-With':'rqly-editor','X-CSRF-Token':csrfToken},body:file});const data=await response.json();if(response.status===401&&!$('session-expired-dialog').open)$('session-expired-dialog').showModal();if(!response.ok)throw new Error(data.error||'图片上传失败，请重试。');if(mediaPurpose==='cover')setCover(data.image.url);else insertImage(data.image.url);status(mediaPurpose==='cover'?'封面已选好，草稿会自动保存。':'图片已插入。修改图片说明后，草稿会自动保存。');}
 catch(error){status(error.message,true);}finally{setBusy(false);$('image-file').value='';}
}
$('upload-image').addEventListener('click',()=>{mediaPurpose='body';$('image-file').click();});$('image-file').addEventListener('change',()=>uploadImage($('image-file').files[0]));
$('body').addEventListener('dragover',event=>{if(event.dataTransfer?.types.includes('Files'))event.preventDefault();});
$('body').addEventListener('drop',event=>{if(event.dataTransfer?.files.length){event.preventDefault();mediaPurpose='body';uploadImage(event.dataTransfer.files[0]);}});
$('body').addEventListener('paste',event=>{const file=[...(event.clipboardData?.files||[])].find(file=>file.type.startsWith('image/'));if(file){event.preventDefault();mediaPurpose='body';uploadImage(file);}});
