function fillGrowth(){if(!island)return;const s=islandStats||{score:0};if(!islandDirty)$('growth-threshold').value=island.growth?.threshold??30;$('admin-growth-status').textContent='真实积累 '+s.score+' 点 · '+(island.growth?.unlocked?'扩岛已解锁':s.eligible?'已经达到目标，可确认扩岛':'还差 '+(s.remaining??30)+' 点解锁扩岛');$('admin-growth-progress').max=island.growth?.threshold??30;$('admin-growth-progress').value=s.score;}
$('confirm-growth').addEventListener('click',()=>{if(!island)return;const target=Number($('growth-threshold').value);if(!island.growth?.unlocked&&(islandStats?.score??0)<target){status('还没有达到目标，可以继续积累或调整成长目标。',true,'island-status');return;}if(confirm('扩岛会让书屋加层、展馆移到新岛，并增加连接桥。保存后才会展示，继续预览吗？')){$('island-phase').value='grown';island.phase='grown';islandEditEpoch++;scene?.updateIsland(island);scene?.setArrange(sceneArranging);islandDirty=true;status('扩岛预览已准备好，请保存并展示。',false,'island-status');}});
function fillDecorations(){$('decoration-settings').replaceChildren();for(const [slot,setting] of Object.entries(rules?.decorationSlots||{})){const label=text('label',setting.label);const select=document.createElement('select');select.dataset.decorationSlot=slot;for(const [value,name] of [['','留白'],['tree','树木'],['bench','长椅'],['lamp','路灯']]){const option=text('option',name);option.value=value;select.append(option);}select.value=island.decorations?.find(d=>d.slot===slot)?.type||'';select.addEventListener('change',()=>{island.decorations=[...document.querySelectorAll('#decoration-settings select')].filter(s=>s.value).map(s=>({slot:s.dataset.decorationSlot,type:s.value}));scene?.updateIsland(island);scene?.setArrange(sceneArranging);});label.append(select);$('decoration-settings').append(label);}}
async function loadManagedMedia(more=false){if(mediaLoading)return;mediaLoading=true;if(!more){mediaOffset=0;$('managed-media').replaceChildren();}status('正在整理图片…',false,'managed-media-status');try{const data=await request('/api/admin/media?offset='+mediaOffset+'&unused='+($('media-filter').value==='unused'?'1':'0'));$('media-storage').textContent=data.storage.count+' 张图片 · '+(data.storage.bytes/1048576).toFixed(1)+' MB / 2048 MB';for(const image of data.images){const card=text('article','','managed-media-card');const img=document.createElement('img');img.src=image.url;img.alt='已上传图片';img.loading='lazy';card.append(img,text('small',image.width+' × '+image.height+' · '+Math.ceil(image.bytes/1024)+' KB · '+image.createdAt.slice(0,10)));const refs=text('div','','media-references');for(const ref of image.references){const b=text('button',({published:'公开',draft:'草稿',trash:'回收站',editing:'编辑中',history:'历史版本'}[ref.status])+' · '+ref.title);b.type='button';b.addEventListener('click',()=>{if(canSwitch()){navigate(ref.status==='trash'?'trash':'content');if(ref.type==='editorDraft')openEditorDraft(ref.id);else {const post=posts.find(p=>p.slug===ref.slug);if(post){if(post.trashedAt)fill(post);else openPost(post).then(()=>{if(ref.type==='history')$('post-history').click();});}}}});refs.append(b);}if(!image.references.length)refs.append(text('p','未使用，可以整理。','muted'));card.append(refs);const actions=text('div','','media-card-actions');for(const [name,purpose] of [['插入正文','body'],['设为封面','cover']]){const b=text('button',name);b.type='button';b.addEventListener('click',()=>{navigate('content');if(editing?.trashedAt)fill({},'blog');if(purpose==='cover')setCover(image.url);else insertImage(image.url);});actions.append(b);}const remove=text('button','删除','danger');remove.type='button';remove.disabled=image.references.length>0;remove.addEventListener('click',async()=>{if(Object.values(localDrafts).some(d=>d.content?.cover===image.url||d.content?.body?.includes(image.url))||$('post-cover').value===image.url||$('body').value.includes(image.url)){status('当前编辑仍使用这张图片，请先移除并保存。',true,'managed-media-status');return;}if(!confirm('永久删除这张未使用图片？需要时只能从服务器备份恢复。'))return;remove.disabled=true;try{await request('/api/admin/media/'+image.filename,{method:'DELETE'});await loadManagedMedia();}catch(e){status(e.message,true,'managed-media-status');remove.disabled=false;}});actions.append(remove);card.append(actions);$('managed-media').append(card);}mediaOffset=data.nextOffset;$('more-media').hidden=mediaOffset===null;status($('managed-media').children.length?'':'这里还没有符合条件的图片。',false,'managed-media-status');}catch(e){status(e.message,true,'managed-media-status');}finally{mediaLoading=false;}}
$('refresh-media').addEventListener('click',()=>loadManagedMedia());$('media-filter').addEventListener('change',()=>loadManagedMedia());$('more-media').addEventListener('click',()=>loadManagedMedia(true));
$('export-content').addEventListener('click',async()=>{try{const data=await request('/api/admin/export');const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='ly-content-'+new Date().toISOString().slice(0,10)+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){status(e.message,true,'dashboard-status');}});

let historyPost=null,historyRevision=null,historySelected=null,historyEpoch=0,historyDraftRevision=null,historyCache=new Map();
$('close-history').addEventListener('click',()=>{historyEpoch++;$('history-dialog').close();});
$('history-dialog').addEventListener('cancel',()=>{historyEpoch++;});
$('post-history').addEventListener('click',async()=>{
 if(!editing||busy)return;const post=editing;historyPost=post;historySelected=null;historyCache=new Map();const epoch=++historyEpoch;$('history-list').replaceChildren();$('history-preview').replaceChildren();$('history-diff').replaceChildren();$('restore-history-version').disabled=true;$('history-dialog').showModal();status('正在读取历史版本…',false,'history-status');
 try{if(dirty)await autosaveDraft();if(autosavePending)await autosavePending;const [data,draft]=await Promise.all([request('/api/admin/posts/'+post.slug+'/history'),request('/api/admin/editor-drafts/post-'+post.slug).catch(error=>{if(error.status===404)return {draft:null};throw error;})]);if(epoch!==historyEpoch||!$('history-dialog').open)return;historyRevision=data.currentRevision;historyDraftRevision=draft.draft?.revision??null;const current=data.versions.find(v=>v.current);historyCache.set(current.id,(await request('/api/admin/posts/'+post.slug+'/history/'+current.id)).version);
 if(epoch!==historyEpoch||!$('history-dialog').open)return;for(const version of data.versions){const b=text('button','','history-version');b.type='button';b.dataset.version=version.id;b.append(text('strong',version.current?'当前保存版本':new Date(version.savedAt).toLocaleString('zh-CN')),text('small',(version.current?'':version.reason+' · ')+(version.published?'当时已发布':'当时是草稿')+' · '+version.characters+' 字'));b.addEventListener('click',()=>selectHistoryVersion(version.id));$('history-list').append(b);}
 status(data.versions.length===1?'尚无旧版本。以后的更新、撤回与删除前，会自动留存；每条内容保留最近 30 个旧版本。':'已保留 '+(data.versions.length-1)+' 个旧版本。载入只修改私有编辑草稿，确认更新发布后才替换公开原文。',false,'history-status');if(historyRevision!==post.revision)status('原文已在其他页面更新。可以查看历史，请重新载入原文后再恢复。',true,'history-status');await selectHistoryVersion(data.versions.find(v=>!v.current)?.id||current.id);
 }catch(error){if(epoch===historyEpoch)status(error.message,true,'history-status');}
});
async function selectHistoryVersion(id){
 const post=historyPost,epoch=++historyEpoch;historySelected=null;$('restore-history-version').disabled=true;$('history-preview').replaceChildren(text('p','正在翻开这个版本…','muted'));try{const data=await request('/api/admin/posts/'+post.slug+'/history/'+id);if(epoch!==historyEpoch||!$('history-dialog').open)return;historySelected=data.version;$('history-preview').innerHTML=data.html;for(const b of $('history-list').children)b.setAttribute('aria-current',b.dataset.version===id?'true':'false');$('restore-history-version').disabled=data.version.current||Boolean(post.trashedAt)||historyRevision!==post.revision;
 const current=[...historyCache.values()][0].content,old=data.version.content;$('history-diff').replaceChildren();const meta=text('p','相对当前保存版本：'+(old.body===current.body?'正文相同':current.body.length+' 字 → '+old.body.length+' 字'),'muted');$('history-diff').append(meta);for(const key of ['title','summary','kind','topic','date','cover','project','organization'])if(JSON.stringify(old[key])!==JSON.stringify(current[key]))$('history-diff').append(text('span',({title:'标题',summary:'摘要',kind:'类型',topic:'分类',date:'日期',cover:'封面',project:'项目资料',organization:'内容归属'}[key])+'有变化','history-change'));
 if(old.body!==current.body){let start=0,end=0;while(start<old.body.length&&start<current.body.length&&old.body[start]===current.body[start])start++;while(end<old.body.length-start&&end<current.body.length-start&&old.body[old.body.length-1-end]===current.body[current.body.length-1-end])end++;const comparison=text('div','','history-comparison');for(const [label,value] of [['当前保存的片段',current.body],['历史版本的片段',old.body]]){const box=text('section','');const sample=text('pre','');sample.append(document.createTextNode((start>24?'…':'')+value.slice(Math.max(0,start-24),start).replace(/\n{2,}/g,'\n')));const changed=value.slice(start,value.length-end);sample.append(text('mark',changed.slice(0,1200)||(value===current.body?'（这一版没有该片段）':'（该片段已删除）')));sample.append(document.createTextNode((changed.length>1200?'…':'')+value.slice(value.length-end,value.length-end+40)+(end>40?'…':'')));box.append(text('h3',label),sample);comparison.append(box);}$('history-diff').append(comparison);}
 }catch(error){if(epoch===historyEpoch){$('history-preview').replaceChildren();status(error.message,true,'history-status');}}
}
$('restore-history-version').addEventListener('click',async()=>{
 if(!historySelected||busy||historySelected.current)return;if(!confirm('将这个版本载入为私有编辑草稿？当前编辑草稿会被替换，公开文章保持现状。核对后可点击“更新发布”。'))return;const post=historyPost,version=historySelected;setBusy(true);$('restore-history-version').disabled=true;clearAutosaveTimers();try{const data=await request('/api/admin/posts/'+post.slug+'/history/'+version.id+'/restore',{method:'POST',headers:{'If-Match':historyRevision},body:JSON.stringify({baseDraftRevision:historyDraftRevision})});delete localDrafts['post-'+post.slug];writeLocalDrafts();posts=posts.map(p=>p.slug===data.post.slug?data.post:p);editorDrafts=editorDrafts.filter(d=>d.id!==data.draft.id);editorDrafts.unshift(draftMetadata(data.draft));historyEpoch++;$('history-dialog').close();await openEditorDraft(data.draft.id,{ignoreLocal:true});status('历史版本已载入编辑草稿。公开原文保持现状；核对后再更新发布。');}catch(error){status(error.message,true,'history-status');}finally{setBusy(false);$('restore-history-version').disabled=false;}
});

function organizedRecord(record){return organizationCore?organizationCore.decorateOrganization(record,organizationCatalog,posts):record;}
function currentOrganization(){return {tags:[...$('org-tags').querySelectorAll('input:checked')].map(i=>i.value),topics:[...$('org-topics').querySelectorAll('input:checked')].map(i=>i.value),series:$('org-series').value,order:Number($('org-order').value)||1,projectSlug:$('kind').value==='project'?'':$('org-project').value};}
function fillOrganization(value={}){
 const o={tags:[],topics:[],series:'',order:1,projectSlug:'',...value};
 for(const [type,key] of [['tag','tags'],['topic','topics']]){const box=$('org-'+key);box.replaceChildren();for(const item of organizationCatalog.items.filter(i=>i.type===type&&(!i.archived||o[key].includes(i.id)))){const label=text('label','','org-check');const input=document.createElement('input');input.type='checkbox';input.value=item.id;input.checked=o[key].includes(item.id);label.append(input,document.createTextNode(item.name+(item.archived?'（已停用）':'')));box.append(label);}if(!box.children.length)box.append(text('small','还没有'+(type==='tag'?'标签':'专题')+'，可到“内容归属”创建。','muted'));}
 const select=$('org-series');select.replaceChildren(text('option','独立文章'));select.firstChild.value='';for(const item of organizationCatalog.items.filter(i=>i.type==='series'&&(!i.archived||i.id===o.series))){const option=text('option',item.name+(item.archived?'（已停用）':''));option.value=item.id;select.append(option);}select.value=o.series;$('org-order').value=o.order;
 const projects=$('org-project');projects.replaceChildren(text('option','暂不关联'));projects.firstChild.value='';for(const post of posts.filter(p=>p.kind==='project'&&(!p.trashedAt||p.slug===o.projectSlug))){const option=text('option',post.title+(post.trashedAt?'（回收站）':post.published?'':'（草稿）'));option.value=post.slug;projects.append(option);}projects.value=o.projectSlug;updateOrganizationSelection();
}
function updateOrganizationSelection(){const o=currentOrganization();$('org-order').disabled=!o.series;$('org-project-label').hidden=$('kind').value==='project';const record=organizedRecord({organization:o}),d=record.organizationDetails;$('org-selection').textContent=d?[...d.tags.map(i=>'#'+i.name),...d.topics.map(i=>'专题：'+i.name),...(d.series?['系列：'+d.series.name+' · 第'+o.order+'篇']:[]),...(d.project?['项目：'+d.project.title]:[])].join(' · '):'';}
function refreshOrganizationControls(){const o=currentOrganization();fillOrganization(o);const select=$('content-organization-filter'),previous=select.value;select.replaceChildren(text('option','全部归属'));select.firstChild.value='';for(const type of ['tag','topic','series'])for(const item of organizationCatalog.items.filter(i=>i.type===type)){const option=text('option',({tag:'标签',topic:'专题',series:'系列'}[type])+' · '+item.name);option.value=item.id;select.append(option);}select.value=previous;}
for(const id of ['org-tags','org-topics','org-series','org-order','org-project','kind'])$(id).addEventListener('change',updateOrganizationSelection);
function resetOrganizationForm() {organizationEdit=null;$('organization-form').reset();$('organization-type').disabled=false;$('save-organization').textContent='创建目录';}
function renderOrganizationList(){const list=$('organization-list');list.replaceChildren();for(const type of ['tag','topic','series']){const section=text('section','','org-group');section.append(text('h3',{tag:'标签',topic:'专题',series:'系列'}[type]));const items=organizationCatalog.items.filter(i=>i.type===type);for(const item of items){const row=text('article','','org-row'),info=text('div');const count=posts.filter(p=>!p.trashedAt&&(p.organization?.tags?.includes(item.id)||p.organization?.topics?.includes(item.id)||p.organization?.series===item.id));info.append(text('strong',item.name),text('small',(item.archived?'已停用 · ':'')+count.length+' 条内容 · '+count.filter(p=>p.published).length+' 条公开'));if(item.description)info.append(text('p',item.description));const actions=text('div','','org-actions'),edit=text('button','编辑'),browse=text('button','查看内容'),remove=text('button','删除','danger');for(const b of [edit,browse,remove])b.type='button';edit.addEventListener('click',()=>{organizationEdit=item.id;$('organization-type').value=item.type;$('organization-type').disabled=true;$('organization-name').value=item.name;$('organization-description').value=item.description;$('organization-archived').checked=item.archived;$('save-organization').textContent='保存修改';$('organization-name').focus();});browse.addEventListener('click',()=>{if(canSwitch()){navigate('content');$('content-organization-filter').value=item.id;renderList();}});remove.addEventListener('click',async()=>{if(organizationCore&&(organizationCore.usesOrganization({organization:currentOrganization()},item.id)||allEditorDrafts().some(d=>organizationCore.usesOrganization(d.content||{},item.id)))){status('当前编辑或暂存草稿仍使用它，请先移除并保存，或改为停用。',true,'organization-status');return;}if(!confirm('删除“'+item.name+'”？仍有引用时会保留，可以改为停用。'))return;remove.disabled=true;try{const data=await request('/api/admin/organization',{method:'PUT',body:JSON.stringify({baseRevision:organizationCatalog.revision,action:'delete',item:{id:item.id}})});organizationCatalog=data.catalog;if(organizationEdit===item.id)resetOrganizationForm();refreshOrganizationControls();renderOrganizationList();status('目录已删除。',false,'organization-status');}catch(e){status(e.message,true,'organization-status');}finally{remove.disabled=false;}});actions.append(edit,browse,remove);row.append(info,actions);section.append(row);}if(!items.length)section.append(text('p','还没有'+{tag:'标签',topic:'专题',series:'系列'}[type]+'。','muted'));list.append(section);}}
$('organization-form').addEventListener('submit',async event=>{event.preventDefault();const button=$('save-organization');if(button.disabled)return;button.disabled=true;try{const data=await request('/api/admin/organization',{method:'PUT',body:JSON.stringify({baseRevision:organizationCatalog.revision,action:organizationEdit?'update':'create',item:{id:organizationEdit,type:$('organization-type').value,name:$('organization-name').value,description:$('organization-description').value,archived:$('organization-archived').checked}})});organizationCatalog=data.catalog;resetOrganizationForm();refreshOrganizationControls();renderOrganizationList();renderList();status('已保存。只有被公开内容使用的目录会对外展示。',false,'organization-status');}catch(e){status(e.message,true,'organization-status');}finally{button.disabled=false;}});
$('cancel-organization').addEventListener('click',resetOrganizationForm);
$('refresh-organization').addEventListener('click',async()=>{try{organizationCatalog=(await request('/api/admin/organization')).catalog;refreshOrganizationControls();renderOrganizationList();renderList();status('已载入最新目录。',false,'organization-status');}catch(e){status(e.message,true,'organization-status');}});
